package gadomancymodern.test;
import gadomancymodern.Gadomancy;
import gadomancymodern.claw.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.gametest.*;
import tc4revival.content.*;

@GameTestHolder("gadomancy") @PrefixGameTestTemplate(false)
public class InfusionClawServerTests {
    protected static InfusionClawEntity claw(GameTestHelper test){var pos=test.absolutePos(new BlockPos(3,4,3));var level=test.getLevel();level.setBlockAndUpdate(pos,Gadomancy.CLAW.get().defaultBlockState());var tile=(InfusionClawEntity)level.getBlockEntity(pos);var data=new CompoundTag();data.putUUID("Owner",java.util.UUID.randomUUID());data.putString("player","ClawOwner");tile.load(data);return tile;}
    protected static ItemStack wand(boolean charged){return TCItems.CASTING_WAND.get().create(WandParts.Rod.GREATWOOD,WandParts.Cap.GOLD,false,charged);}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void insertionLockAndRecoveryPreserveOriginalRules(GameTestHelper test){var claw=claw(test);var wand=wand(true);test.assertTrue(claw.canPlaceItem(0,wand)&&!claw.canPlaceItem(0,new ItemStack(Items.STICK))&&!claw.canPlaceItem(0,TCItems.CASTING_WAND.get().create(WandParts.Rod.GREATWOOD,WandParts.Cap.GOLD,true,true)),"Only non-sceptre unfocused casting implements");var focused=wand.copy();WandFocusItem.attach(focused,new ItemStack(TCItems.PRIMAL_FOCUS.get()));test.assertTrue(!claw.canPlaceItem(0,focused),"Attached focus is rejected");claw.setItem(0,wand);claw.locked(true);test.assertTrue(claw.getSlotsForFace(Direction.DOWN).length==0&&!claw.canTakeItemThroughFace(0,wand,Direction.NORTH),"No bottom automation and usable locked wand stays");test.assertTrue(claw.removeItem(0,1)==wand,"Lock restricts automation, not manual removal");claw.setItem(0,wand(false));test.assertTrue(claw.canTakeItemThroughFace(0,claw.getItem(0),Direction.UP),"Exhausted locked wand can be replaced");var tag=claw.saveWithoutMetadata();var copy=new InfusionClawEntity(claw.getBlockPos(),claw.getBlockState());copy.load(tag);test.assertTrue(copy.locked()&&copy.owner().equals(claw.owner())&&ItemStack.isSameItemSameTags(copy.getItem(0),claw.getItem(0))&&!copy.running(),"Save retains owner/wand/lock and does not invent persisted legacy timer");test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty",timeoutTicks=470)
    public static void actualRedstoneDelayCreatesThaumonomiconWithOfflineOwner(GameTestHelper test){var claw=claw(test);var level=test.getLevel();var target=claw.getBlockPos().below();level.setBlockAndUpdate(target,Blocks.BOOKSHELF.defaultBlockState());claw.setItem(0,wand(false));var firstLoad=new InfusionClawEntity(claw.getBlockPos(),claw.getBlockState());firstLoad.powerChanged(true);test.assertTrue(!firstLoad.running(),"Initial powered state does not count as a rising edge");claw.powerChanged(false);claw.powerChanged(true);test.assertTrue(claw.running()&&!claw.canPlaceItem(0,wand(true))&&claw.removeItem(0,1).isEmpty(),"Rising edge starts and protects the wand during the animation");test.runAfterDelay(280,()->test.assertTrue(level.getBlockState(target).is(Blocks.BOOKSHELF),"No premature activation before 290 ticks"));test.runAfterDelay(305,()->{test.assertTrue(level.isEmptyBlock(target),"Real fake-player wand interaction consumes bookshelf");var output=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(target).inflate(3),entity->entity.getItem().is(TCItems.THAUMONOMICON.get()));test.assertTrue(output.size()==1&&claw.running(),"Exactly one book produced and claw is still retracting");level.setBlockAndUpdate(target,Blocks.BOOKSHELF.defaultBlockState());});test.runAfterDelay(450,()->{test.assertTrue(!claw.running()&&level.getBlockState(target).is(Blocks.BOOKSHELF),"Held redstone never loops a second click");test.succeed();});}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void registeredClawBehaviorPaysAllPrimalsAndReceivesCalculatedRisk(GameTestHelper test){var claw=claw(test);var level=test.getLevel();var target=claw.getBlockPos().below();level.setBlockAndUpdate(target,Blocks.DIAMOND_BLOCK.defaultBlockState());var amount=new java.util.concurrent.atomic.AtomicInteger();ClawBehavior custom=new ClawBehavior(){@Override public boolean accepts(net.minecraft.server.level.ServerLevel world,BlockPos pos){return world==level&&pos.equals(target);}@Override public boolean consumesVis(){return true;}@Override public void instability(net.minecraft.server.level.ServerLevel world,BlockPos pos,int value){amount.set(value);}@Override public int comparator(net.minecraft.server.level.ServerLevel world,BlockPos pos){return 9;}};ClawBehavior.register(custom);try{claw.setItem(0,wand(false));test.assertTrue(!claw.start(),"Insufficient vis prevents activation");claw.setItem(0,wand(true));var before=claw.getItem(0).copy();test.assertTrue(claw.comparator()==9&&claw.click(),"Custom behavior executes through actual wand dispatch");for(var aspect:tc4revival.aspect.TCAspects.catalog().primals())test.assertTrue(TCItems.CASTING_WAND.get().vis(claw.getItem(0),aspect)<TCItems.CASTING_WAND.get().vis(before,aspect),"Random primal cost debited: "+aspect.tag());test.assertTrue(amount.get()==ClawInstability.calculate(50,false,1,false,false),"Custom handler receives exact wand instability");}finally{ClawBehavior.handlers().remove(custom);}test.succeed();}
}
